import re

def parse(lines):
    hdr = re.compile(r'^== disasm: #<ISeq:(?P<name>.*)@(?P<file>[^@:]+):(?P<line>\d+) \((?P<range>[^)]*)\)>\s*$')
    ins = re.compile(r'^(?P<pos>\d{4,})\s+(?P<insn>\S+)(?:\s+(?P<rest>.*?))?\s*$')
    lt = re.compile(r'^local table \(size: (?P<size>\d+), argc: (?P<argc>\d+) \[(?P<opts>.*)\]\)\s*$')
    loc = re.compile(r'\[\s*(?P<idx>\d+)\]\s*(?P<name>[^\s@\[]+)@(?P<slot>\d+)(?:<(?P<flags>[^>]*)>)?')
    lnev = re.compile(r'\s*\(\s*(\d+)\)(?:\[(\w*)\])?$')
    evonly = re.compile(r'(?:^|\s+)\[(\w+)\]$')
    iseqs = {'name': 'iseqs', 'kind': 'table', 'lines': [], 'records': []}
    insns = {'name': 'instructions', 'kind': 'table', 'lines': [], 'records': []}
    ltabs = {'name': 'local_tables', 'kind': 'table', 'lines': [], 'records': []}
    locs = {'name': 'locals', 'kind': 'table', 'lines': [], 'records': []}
    cur = ''
    for i, l in enumerate(lines):
        if not l.strip():
            continue
        m = hdr.match(l)
        if m:
            cur = m.group('name')
            iseqs['lines'].append(i)
            iseqs['records'].append({'iseq': cur, 'file': m.group('file'), 'line': int(m.group('line')), 'range': m.group('range')})
            continue
        m = lt.match(l)
        if m:
            ltabs['lines'].append(i)
            ltabs['records'].append({'iseq': cur, 'size': int(m.group('size')), 'argc': int(m.group('argc')), 'details': m.group('opts')})
            continue
        if re.match(r'^\[\s*\d+\]', l):
            found = False
            for lm in loc.finditer(l):
                found = True
                locs['records'].append({'iseq': cur, 'index': int(lm.group('idx')), 'name': lm.group('name'), 'slot': int(lm.group('slot')), 'flags': lm.group('flags') or ''})
            if found:
                locs['lines'].append(i)
            continue
        m = ins.match(l)
        if m:
            rest = m.group('rest') or ''
            line = ''
            ev = ''
            em = lnev.search(rest)
            if em:
                line = int(em.group(1))
                ev = em.group(2) or ''
                rest = rest[:em.start()]
            else:
                em = evonly.search(rest)
                if em:
                    ev = em.group(1)
                    rest = rest[:em.start()]
            insns['lines'].append(i)
            insns['records'].append({'iseq': cur, 'pos': m.group('pos'), 'insn': m.group('insn'), 'operands': rest.strip(), 'line': line, 'events': ev})
            continue
    blocks = [b for b in (iseqs, insns, ltabs, locs) if b['records']]
    return {'blocks': blocks, 'skip': []}
